            u.set("inner", "1").unwrap();
            u.delete("user:ana");
            Err("inner failed".to_string())
        });
        assert_eq!(inner, Err("inner failed".to_string()));
        assert_eq!(t.get("inner"), None);
        assert_eq!(t.get("user:ana"), Some("10"));
