    s.set("été", "3").unwrap();
    assert_eq!(s.keys(), vec!["Zed", "a=b", "alpha", "été"]);
    assert_eq!(s.get("alpha"), Some(""));
    assert_eq!(s.get("ALPHA"), None);
    s.set("alpha", "multi word value").unwrap();
    assert_eq!(s.get("alpha"), Some("multi word value"));
    assert_eq!(s.len(), 4);
    assert!(s.delete("Zed"));
    assert!(!s.delete("Zed"));
