    s.advance(2);
    assert_eq!((s.get("tmp"), s.ttl("tmp"), s.len()), (Some("x"), Some(1), 5));
    s.advance(1);
    assert_eq!((s.get("tmp"), s.ttl("tmp"), s.len()), (None, None, 4));
    assert!(!s.keys().contains(&"tmp".to_string()));
    assert!(!s.delete("tmp"));
