        t.advance(7);
        Err(())
    });
    assert!(r.is_err());
    assert_eq!(s.get("tmp"), None);
    assert_eq!(s.len(), 4);
}

#[test]
fn rollback_discards_events() {
    let mut s = store();
    let id = s.subscribe("");
    s.set("before", "1").unwrap();
    let r: Result<(), ()> = s.transaction(|t| {
        t.set("during", "1").unwrap();
        t.delete("user:ana");
        Err(())
    });
    assert!(r.is_err());
    let ok: Result<(), ()> = s.transaction(|t| {
        t.set("kept", "1").unwrap();
        Ok(())
    });
    assert!(ok.is_ok());
    assert_eq!(s.take_events(id).unwrap(), vec![
        Event::Set("before".to_string()),
        Event::Set("kept".to_string()),
    ]);
}

