use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StoreError {
    BadKey(String),
    Full(usize),
    BadCapacity,
    BadTtl,
    Parse(usize),
    UnknownSubscription(usize),
}

impl fmt::Display for StoreError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StoreError::BadKey(k) => write!(f, "bad key {:?}", k),
            StoreError::Full(n) => write!(f, "store is full ({} keys)", n),
            StoreError::BadCapacity => write!(f, "capacity must be at least 1"),
            StoreError::BadTtl => write!(f, "ttl must be at least 1"),
            StoreError::Parse(n) => write!(f, "cannot parse line {}", n),
            StoreError::UnknownSubscription(n) => write!(f, "no subscription {}", n),
        }
    }
}

impl std::error::Error for StoreError {}

