        ("a=1\n\n=value\n", 3),
        ("a b=1\n", 1),
        ("a=1\nb=\\x\n", 2),
        ("a=1\nb\\nc=1\n", 2),
        ("a=1\nb=ends with backslash\\", 2),
        ("a\\=b\n", 1),
